import { beforeEach, describe, expect, it } from 'vitest';
import { TestBed } from '@angular/core/testing';
import { Watchlist } from '../app/watchlist/watchlist';
import { WatchlistStore } from '../app/watchlist-store';
import { TmdbMovie } from '../app/movie';

function movie(id: number, title: string): TmdbMovie {
  return { id, title, release_date: '2024-01-01', poster_path: null, overview: 'Test overview' };
}

describe('watchlist ordering', () => {
  beforeEach(() => {
    TestBed.resetTestingModule();
    localStorage.clear();
    TestBed.configureTestingModule({});
  });

  it('lists unwatched movies before watched movies', () => {
    const store = TestBed.inject(WatchlistStore);
    store.add(movie(1, 'Watched one'));
    store.add(movie(2, 'Unwatched alpha'));
    store.add(movie(3, 'Unwatched beta'));
    store.add(movie(4, 'Watched two'));
    store.toggleWatched(1);
    store.toggleWatched(4);

    const fixture = TestBed.createComponent(Watchlist);
    fixture.detectChanges();

    expect(fixture.componentInstance.movies().map((m) => m.id)).toEqual([2, 3, 1, 4]);
  });

  it('moves a movie after the unwatched ones when it is marked watched', () => {
    const store = TestBed.inject(WatchlistStore);
    store.add(movie(1, 'First'));
    store.add(movie(2, 'Second'));
    store.add(movie(3, 'Third'));
    store.toggleWatched(2);

    const fixture = TestBed.createComponent(Watchlist);
    const component = fixture.componentInstance;
    fixture.detectChanges();

    expect(component.movies().map((m) => m.id)).toEqual([1, 3, 2]);

    component.toggleWatched(1);
    fixture.detectChanges();

    expect(component.movies().map((m) => m.id)).toEqual([3, 1, 2]);
  });

  it('renders unwatched titles before watched titles', () => {
    const store = TestBed.inject(WatchlistStore);
    store.add(movie(1, 'Watched one'));
    store.add(movie(2, 'Unwatched alpha'));
    store.add(movie(3, 'Unwatched beta'));
    store.add(movie(4, 'Watched two'));
    store.toggleWatched(1);
    store.toggleWatched(4);

    const fixture = TestBed.createComponent(Watchlist);
    fixture.detectChanges();

    const text = fixture.nativeElement.textContent ?? '';
    expect(text).toContain('Unwatched alpha');
    expect(text).toContain('Watched one');
    const firstUnwatched = text.indexOf('Unwatched alpha');
    const lastWatched = text.lastIndexOf('Watched two');
    expect(firstUnwatched).toBeGreaterThan(-1);
    expect(lastWatched).toBeGreaterThan(-1);
    expect(firstUnwatched).toBeLessThan(lastWatched);
  });
});
```

